import React, { useState, useEffect, useCallback, useRef } from 'react';
import styled from '@emotion/styled';
import { PanelRightClose, PanelRightOpen, AlertCircle } from 'lucide-react';
import { theme } from '@atlantis/shared';
import mermaid from 'mermaid';

mermaid.initialize({ startOnLoad: false, theme: 'dark', securityLevel: 'loose' });

const darkScroll = `
  &::-webkit-scrollbar { width: 6px; }
  &::-webkit-scrollbar-thumb { background: ${theme.colors.border}; border-radius: 3px; }
`;

const Pane = styled.div`
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  background: #1a1f2e;
`;

const PaneHeader = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 ${theme.spacing.md};
  height: 36px;
  background: ${theme.colors.sidebarBg};
  border-bottom: 1px solid ${theme.colors.sidebarBorder};
  flex-shrink: 0;
`;

const PaneTitle = styled.span`
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: ${theme.colors.sidebarTextMuted};
  font-family: ${theme.typography.fontFamily};
`;

const CollapseBtn = styled.button`
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  background: none;
  border: none;
  border-radius: ${theme.borderRadius.sm};
  cursor: pointer;
  color: ${theme.colors.sidebarTextMuted};
  transition: background 0.12s, color 0.12s;
  &:hover { background: ${theme.colors.sidebarHover}; color: ${theme.colors.sidebarText}; }
`;

const PreviewContent = styled.div`
  flex: 1;
  overflow: auto;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: ${theme.spacing.xl};
  ${darkScroll}
  & svg { max-width: 100%; height: auto; }
`;

const ErrorBox = styled.div`
  margin: ${theme.spacing.lg};
  padding: ${theme.spacing.md};
  background: rgba(248, 113, 113, 0.08);
  border: 1px solid rgba(248, 113, 113, 0.25);
  border-radius: ${theme.borderRadius.md};
  color: #f87171;
  font-size: 12px;
  font-family: ${theme.typography.fontFamilyMono};
  line-height: 1.5;
  display: flex;
  gap: 8px;
  align-items: flex-start;
  flex-shrink: 0;
`;

const CollapsedTab = styled.button`
  position: relative;
  flex-shrink: 0;
  width: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 4px;
  background: ${theme.colors.sidebarBg};
  border: 1px solid ${theme.colors.sidebarBorder};
  border-right: none;
  border-radius: ${theme.borderRadius.md} 0 0 ${theme.borderRadius.md};
  cursor: pointer;
  color: ${theme.colors.sidebarTextMuted};
  transition: color 0.12s, background 0.12s;
  align-self: center;
  &:hover { background: ${theme.colors.sidebarHover}; color: ${theme.colors.sidebarText}; }
`;

const VerticalLabel = styled.span`
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-family: ${theme.typography.fontFamily};
  writing-mode: vertical-rl;
`;

interface MermaidPreviewPaneProps {
  code: string;
  collapsed: boolean;
  onToggleCollapse: () => void;
}

export function MermaidPreviewPane({ code, collapsed, onToggleCollapse }: MermaidPreviewPaneProps) {
  const [svg, setSvg] = useState('');
  const [error, setError] = useState<string | null>(null);
  const renderIdRef = useRef(0);

  const render = useCallback(async (src: string) => {
    if (!src.trim()) { setSvg(''); setError(null); return; }
    const id = ++renderIdRef.current;
    try {
      const elemId = 'mermaid-' + Date.now();
      const { svg: result } = await mermaid.render(elemId, src);
      if (renderIdRef.current === id) { setSvg(result); setError(null); }
    } catch (e: unknown) {
      if (renderIdRef.current === id) {
        setError(e instanceof Error ? e.message : String(e));
        setSvg('');
      }
    }
  }, []);

  useEffect(() => {
    const t = setTimeout(() => render(code), 300);
    return () => clearTimeout(t);
  }, [code, render]);

  if (collapsed) {
    return (
      <CollapsedTab onClick={onToggleCollapse} title="Show preview">
        <PanelRightOpen size={14} />
        <VerticalLabel>Preview</VerticalLabel>
      </CollapsedTab>
    );
  }

  return (
    <Pane>
      <PaneHeader>
        <PaneTitle>Preview</PaneTitle>
        <CollapseBtn onClick={onToggleCollapse} title="Collapse preview">
          <PanelRightClose size={15} />
        </CollapseBtn>
      </PaneHeader>
      {error && (
        <ErrorBox>
          <AlertCircle size={14} style={{ flexShrink: 0, marginTop: 1 }} />
          {error}
        </ErrorBox>
      )}
      <PreviewContent dangerouslySetInnerHTML={{ __html: svg }} />
    </Pane>
  );
}
