declare let __webpack_public_path__: string;


function remarkCallouts() {
  return (tree: any) => {
    function walk(node: any) {
      if (node.type === 'blockquote') {
        const first = node.children?.[0];
        if (first?.type === 'paragraph') {
          const inline = first.children?.[0];
          if (inline?.type === 'text') {
            const m = inline.value?.match(/^\[!(NOTE|TIP|WARNING|CAUTION|IMPORTANT)\]\s*/i);
            if (m) {
              inline.value = inline.value.slice(m[0].length);
              if (!inline.value.trim() && first.children.length === 1) node.children.shift();
              node.data = node.data ?? {};
              node.data.hName = 'div';
              node.data.hProperties = { 'data-callout': m[1].toUpperCase() };
            }
          }
        }
      }
      node.children?.forEach(walk);
    }
    walk(tree);
  };
}

