function makeHeading(level: 1 | 2 | 3 | 4) {
  return function HeadingComponent({ children, ...props }: React.HTMLAttributes<HTMLHeadingElement>) {
    const Tag = `h${level}` as 'h1' | 'h2' | 'h3' | 'h4';
    const text = childrenToText(children);
    const id = slugify(text);
    return (
      <Tag id={id} {...props}>
        {children}
        <a className="heading-anchor" href={`#${id}`} aria-label={`Link to "${text}"`}>
          <LinkIcon size={14} />
        </a>
      </Tag>
    );
  };
}

interface MarkdownViewerProps {
  file: string;
  prevEntry?: NavEntry | null;
  nextEntry?: NavEntry | null;
  onNavigate?: (entry: NavEntry) => void;
  scrollToId?: string | null;
  onScrolled?: () => void;
}

export function MarkdownViewer({ file, prevEntry, nextEntry, onNavigate, scrollToId, onScrolled }: MarkdownViewerProps) {
  const [content, setContent] = useState<string | null>(null);
  const [activeHeadingId, setActiveHeadingId] = useState<string | null>(null);
  const articleRef = useRef<HTMLElement>(null);

  useEffect(() => {
    setContent(null);
    fetch(`${__webpack_public_path__}content/${file}`)
      .then((res) => {
        if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
        return res.text();
      })
      .then(setContent)
      .catch((err) => setContent(`> **Error loading \`${file}\`:** ${err.message}`));
  }, [file]);

  // Scroll to a specific heading when requested (e.g. from search)
  useEffect(() => {
    if (!scrollToId || !content || !articleRef.current) return;
    const tryScroll = () => {
      const el = articleRef.current?.querySelector(`#${CSS.escape(scrollToId)}`);
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'start' });
        setActiveHeadingId(scrollToId);
        onScrolled?.();
      }
    };
    // Small delay to ensure the DOM has rendered
    const timer = setTimeout(tryScroll, 150);
    return () => clearTimeout(timer);
  }, [scrollToId, content, onScrolled]);

  useEffect(() => {
    if (!content || !articleRef.current) return;
    const headingEls = articleRef.current.querySelectorAll('h2[id], h3[id]');
    if (!headingEls.length) return;
    const observer = new IntersectionObserver(
      (entries) => {
        const visible = entries.filter((e) => e.isIntersecting);
        if (visible.length) setActiveHeadingId(visible[0].target.id);
      },
      { rootMargin: '-10% 0% -60% 0%', threshold: 0 },
    );
    headingEls.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, [content]);


  if (content === null) return <LoadingText>Loading…</LoadingText>;

  const headings = extractHeadings(content);
  const showNav = prevEntry || nextEntry;

  return (
    <PageWrapper>
      <ArticleWrapper>
        <Article ref={articleRef}>
          <ReactMarkdown
            remarkPlugins={[remarkGfm, remarkMath, remarkCallouts]}
            rehypePlugins={[rehypeRaw, rehypeKatex]}
            components={{
              div({ node, children, ...props }) {
                const calloutType = (props as any)['data-callout'] as string | undefined;
                if (calloutType) return <Callout type={calloutType as CalloutType}>{children}</Callout>;
                return <div {...props}>{children}</div>;
              },
              h1: makeHeading(1) as any,
              h2: makeHeading(2) as any,
              h3: makeHeading(3) as any,
              h4: makeHeading(4) as any,
              pre: ({ children }) => <>{children}</>,
              code({ className, children }) {
                const lang = /language-(\w+)/.exec(className ?? '')?.[1];
                const code = String(children).replace(/\n$/, '');
                if (lang === 'mermaid') return <MermaidBlock code={code} />;
                if (lang === 'chart') return <ChartBlock code={code} />;
                if (lang === 'clock') return <ClockBlock code={code} />;
                if (lang === 'vocabulary') return <VocabularyBlock code={code} />;
                if (lang || code.includes('\n')) return <CodeBlock lang={lang} code={code} />;
                return <code className={className}>{children}</code>;
              },
            }}
          >
            {content}
          </ReactMarkdown>
        </Article>

        {showNav && (
          <NavFooter>
            {prevEntry ? (
              <NavCard align="left" onClick={() => onNavigate?.(prevEntry)}>
                <NavCardLabel><ChevronLeft size={13} /> Previous</NavCardLabel>
                <NavCardTitle>{prevEntry.name}</NavCardTitle>
              </NavCard>
            ) : <div style={{ flex: 1 }} />}
            {nextEntry ? (
              <NavCard align="right" onClick={() => onNavigate?.(nextEntry)}>
                <NavCardLabel>Next <ChevronRight size={13} /></NavCardLabel>
                <NavCardTitle>{nextEntry.name}</NavCardTitle>
              </NavCard>
            ) : <div style={{ flex: 1 }} />}
          </NavFooter>
        )}
      </ArticleWrapper>

      <TableOfContents headings={headings} activeId={activeHeadingId} />
    </PageWrapper>
  );
}

export default MarkdownViewer;
